/****************************************************************************
 * Data plane
 *
 * transmit hands the frame to the vendor TX queue via bmsg_tx_sender();
 * returning a negated errno makes the upper half recycle the NetPKT.
 * receive returns NULL to signal "no packet available".
 ****************************************************************************/

static int bk7258_wifi_ifup(FAR struct netdev_lowerhalf_s *lower)
{
  FAR struct bk7258_wifi_s *priv =
    (FAR struct bk7258_wifi_s *)lower;

  /* PROBE ONLY -- raising carrier here couples it to the administrative
   * `ifconfig up` instead of to the association state, so a frame can be
   * sent while not associated.  That is deliberate for the data-plane TX
   * experiment: it makes the moment the first frame leaves controllable from
   * the console without decoding a closed-source connection event.
   *
   * Before this driver is integrated for real, carrier must move to the
   * association event.  The only candidate slot is ._set_sta_status
   * (bk7258_wifi_adapter.c), whose `void *info` payload is not yet decoded --
   * that decoding is the actual work item, not this shortcut.
   *
   * netdev_lower_carrier_on() takes netdev.d_lock, which is an rmutex_t, and
   * d_ifup is invoked from netdev_ioctl.c without that lock held, so this is
   * safe on both counts.
   */

  bk7258_wifi_lower_carrier_on(priv);
  return OK;
}

static int bk7258_wifi_ifdown(FAR struct netdev_lowerhalf_s *lower)
{
  FAR struct bk7258_wifi_s *priv =
    (FAR struct bk7258_wifi_s *)lower;

  bk7258_wifi_lower_carrier_off(priv);
  return OK;
}

