int bk7258_wifi_lower_tx_raw(FAR const uint8_t *frame, uint16_t len)
{
  FAR struct bk7258_wifi_s *priv = &g_bk7258_wifi;
  struct pbuf *p;
  int ret;

  if (frame == NULL)
    {
      return -EINVAL;
    }

  /* Strictly greater than the header: rwnx_sg_init() builds the first scatter
   * segment as (payload + sizeof(ETH_HDR_T), len - sizeof(ETH_HDR_T)), so a
   * frame of exactly 14 bytes would describe a zero-length segment. */

  if (len <= BK7258_ETH_HDR_LEN || len > BK7258_WIFI_FRAME_MAX)
    {
      return -EMSGSIZE;
    }

  if (!priv->registered)
    {
      return -ENODEV;
    }

  /* PBUF_RAW_TX reserves the link-layer headroom the vendor TX path prepends
   * in place; the EAPOL injection path allocates identically
   * (hostapd_intf.c:1499). */

  p = pbuf_alloc(PBUF_RAW_TX, len, PBUF_RAM);
  if (p == NULL)
    {
      return -ENOMEM;
    }

  memcpy(p->payload, frame, len);

  /* priv->vif_idx has no assignment anywhere in the tree and is therefore the
   * zero from static initialisation.  Zero happens to be the correct STA vif
   * -- the reference TX descriptors log vif=0 -- but that is a coincidence,
   * not a design: it must be filled from the association event before this
   * driver is integrated.  Logged below so a wrong value is visible instead
   * of silently dropped by bmsg_tx_handler(), which returns without freeing
   * when vif_idx == INVALID_VIF_IDX (rw_task.c). */

  syslog(LOG_WARNING, "[BK7258] txraw len=%u vif=%u\n",
         (unsigned)len, (unsigned)priv->vif_idx);

  ret = bmsg_tx_sender(p, priv->vif_idx);

  /* bmsg_tx_sender() takes its own reference and releases it if the queue push
   * fails, so the reference from pbuf_alloc() is ours to drop in both paths. */

  pbuf_free(p);

  if (ret != BK_OK)
    {
      return ret == BK_ERR_NO_MEM ? -ENOMEM : -EIO;
    }

  return OK;
}

