+static bool bk7258_otp_wait_ready(void)
+{
+  unsigned int retry;
+
+  for (retry = 0; retry < 10000; retry++)
+    {
+      if ((getreg32(BK7258_OTP_STATUS) & BK7258_OTP_STATUS_BUSY) == 0)
+        {
+          return true;
+        }
+    }
