+static bool bk7258_otp_activate(void)
+{
+  sys_ll_set_cpu_device_clk_enable_otp_cken(1);
+  up_udelay(10);
+  sys_ll_set_cpu_power_sleep_wakeup_pwd_encp(0);
+  up_udelay(10);
+  modifyreg32(BK7258_OTP_HARDWARE, 0, BK7258_OTP_HARDWARE_ACTIVE);
+  return bk7258_otp_wait_ready();
