+static bool bk7258_otp1_is_readable(uint32_t location)
+{
+  uint32_t permission;
+  uint32_t mask;
+
+  permission = (getreg32(BK7258_OTP_LCKWD + (location / 8) * 4) >>
+                ((location % 8) * 4)) & UINT32_C(0xf);
+  mask = (getreg32(BK7258_OTP_MASK + (location / 128) * 4) >>
+          (((location % 128) / 8) * 2)) & UINT32_C(0x3);
+  return (permission > mask ? permission : mask) <= BK7258_OTP_READ_ONLY;
+}
