+static bool bk7258_otp2_is_readable(uint32_t location)
+{
+  uint32_t permission;
+  uint32_t mask;
+
+  permission = (getreg32(BK7258_OTP2_LCKWD + (location / 256) * 4) >>
+                (((location % 256) / 32) * 4)) & UINT32_C(0xf);
+  mask = (getreg32(BK7258_OTP2_MASK + (location / 512) * 4) >>
+          (((location % 512) / 32) * 2)) & UINT32_C(0x3);
