+static void bk7258_otp_copy_words(uint32_t base, uint32_t offset,
+                                  uint8_t *buf, uint32_t size)
+{
+  while (size != 0)
+    {
+      uint32_t word = getreg32(base + (offset & ~UINT32_C(3)));
+      uint32_t start = offset & UINT32_C(3);
+      uint32_t count = size < 4 - start ? size : 4 - start;
+      uint32_t i;
+
+      for (i = 0; i < count; i++)
+        {
+          buf[i] = (uint8_t)(word >> ((start + i) * 8));
+        }
+
+      buf += count;
+      offset += count;
+      size -= count;
+    }
+}
