+bk_err_t bk_otp_apb_read(otp1_id_t item, uint8_t *buf, uint32_t size)
+{
+  const struct bk7258_otp_item_s *entry;
+  uint32_t location;
+
+  if (item >= 32)
+    {
+      return BK_ERR_OTP_BASE - 14;
+    }
+
+  entry = &g_otp1_map[item];
+  if (entry->allocated_size == 0 || (size != 0 && buf == NULL))
+    {
+      return BK_FAIL;
+    }
+
+  if (size > entry->allocated_size)
+    {
+      return BK_ERR_OTP_BASE - 2;
+    }
+
+  if (!bk7258_otp_activate())
+    {
+      bk7258_otp_sleep();
+      return BK_ERR_OTP_BASE - 13;
+    }
+
+  location = entry->offset / 4;
+  if (!bk7258_otp1_is_readable(location))
+    {
+      bk7258_otp_sleep();
+      return BK_ERR_OTP_BASE - 3;
+    }
+
+  bk7258_otp_copy_words(BK7258_OTP_DATA, entry->offset, buf, size);
+  bk7258_otp_sleep();
+  return BK_OK;
